	getModule() {
		return this._backend.Module;
	}

	noMusDrums(data) {
		// see MUS_HEADER format in https://gitlab.com/torihino/roboplay/-/blob/master/players/src/mus.h?ref_type=heads

		// at offset 0x3f8b the MUS file names the used "drumkit" files (SM1/SM2).. (some files seem to contain
		// total garbage in this area - inconsistent with the above struct def, e.g. including trailing "SM1" extension
		// etc as well. probably the idiots just did not know how to use the file format, like putting "drumkit" comments
		// into the "title" field rather that just setting the correct info in the "drumkit" field). It is unclear if at
		// least the 'NO DRUMS' marker is used consistently - or if NULL strings might have the same meaning.

		let str = 'NO DRUMS';
		let charCodes = [...str].map(char => char.charCodeAt(0));

		for (let i = 0; i<str.length; i++) {
			if(data[0x3f8b + i] != charCodes[i]) {
				return false;
			}
		}
		return true;
	}
	getDrumKitName(data) {
		// configured sample kit name is often garbage and traditional players then
		// use the songs name as a fallback. but trial and error file access on the
		// web may be interpreted as DOS attack - and users being blocked - and this
		// player therefore depends on the garbage actually being cleaned up

		let r= "";
		for (let i = 0; i<8; i++) {
			r += String.fromCharCode(data[0x3f8b + i])
		}
		return r.trim();
	}
	getVersion(data) {
		return data[0x3f93];
	}
	getDeviceId(data) {
		return data[0x3ffe];
	}
	convertProData(data) {
		let value = 0x00;
		for(let i = 0; i < 0x3F00; i++) {
			data[7+i] ^= value;
			value = (value + 1) & 0xff;
		}
		data[0x3f93] = 2; 	// make it SoundTracker V2.0
	}
	updateSongInfo(result) {
		// KSS does nor allow for the meta info available in MUS - so let's keep it here
		result.title= this._title;
		result.track= 0;
		result.artist= this._author;
		result.copyright= "";
		result.tracks= 1;
	}

	camelize(str) {
		return  (" " + str).toLowerCase().replace(/[^a-zA-Z0-9]+(.)/g,
			function(match, chr) {
				// matches stating from the delimiter ending with the word's 1st char (which is also in chr)
				return match.toUpperCase();
			});
	}

	stringify(data) {
		let s = "";
		for (let i = 0; i<data.length; i++) {
			let c= data[i];
			if (!c) break;

			s += String.fromCharCode(c)
		}

		return this.camelize(s.trim());
	}

	getASCIIByteArray(str) {
		var byteArray = new Uint8Array(str.length + 1);
		for (var i= 0; i<str.length; i++) {
			byteArray[i] = str.charCodeAt(i);
		}
		byteArray[i] = 0;
		return byteArray;
	}

	requestFile(name) {
		// triggers/checks status of async file loading

		// reminder: the fileRequestCallback expects to be invoked from the
		// C/C++ side

		let buf = this.getModule()._malloc(name.length);
		this.getModule().HEAPU8.set(this.getASCIIByteArray(name), buf);
		let r=  ScriptNodePlayer.getInstance()._fileRequestCallback(buf);
		this.getModule()._free(buf);

		return r;
	}

	getPlayerInfo(data) {
		const DEVICE_MUSIC = 0x01;	// i.e. percussion mode

		switch(this.getVersion(data)) {
			case 0x00:
			case 0x01:
				if(this.getDeviceId(data) == DEVICE_MUSIC)
					return "FAC SoundTracker v1.0  6CH MSX-MUSIC + PERCUSSION";
				else
					return "FAC SoundTracker v1.0  9CH MSX-AUDIO";
			case 0x02:
				if(this.getDeviceId(data)  == DEVICE_MUSIC)
					return "FAC SoundTracker v2.0  6CH MSX-MUSIC + PERCUSSION";
				else
					return "FAC SoundTracker v2.0  9CH MSX-AUDIO";
			case 0x03:
				if(this.getDeviceId(data)  == DEVICE_MUSIC)
					return "FAC SoundTracker PRO  6CH MSX-MUSIC + PERCUSSION";
				else
					return "FAC SoundTracker PRO  9CH MSX-AUDIO";
			default:
				return "Unknown tracker version";
		}
	}


